    for i in range(N):
        for j in range(N):
            midpoints.append((i + 0.5, j + 0.5))

    max_t = 0.0
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    # Since we can't try all combinations, let's try a heuristic:
    # Randomly sample configurations with 'max_ants' ants.
    import random
    for _ in range(1000):
        subset = random.sample(midpoints, max_ants)
        dirs = [random.choice(directions) for _ in range(max_ants)]
        ants = [[subset[i][0], subset[i][1], dirs[i][0], dirs[i][1]] for i in range(max_ants)]
